package wb;
import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class AddressProbe {
 static int n;static void ok(boolean b){if(!b)throw new AssertionError("case "+(n+1));n++;}
 static JSONObject fixture()throws Exception{return new JSONObject().put("country","中国").put("province","广东省").put("city","深圳市").put("district","南山区").put("street","科技路").put("number","8号").put("secret","must-not-leak");}
 static void idle(AddressResolver r)throws Exception{long end=System.nanoTime()+3000000000L;synchronized(r){while(!r.outstanding.isEmpty()){long left=(end-System.nanoTime())/1000000;if(left<=0)throw new AssertionError("worker not completed");r.wait(left);}}}
 public static void main(String[] a)throws Exception{
  JSONObject f=fixture(),street=AddressPolicy.format(f,15);ok(street.getString("display_name").contains("深圳市南山区科技路8号附近"));ok(!street.has("secret"));ok(!AddressPolicy.format(f,150).has("street"));ok(!AddressPolicy.format(f,35).has("number"));ok(!AddressPolicy.format(f,1500).has("district"));ok(AddressPolicy.format(f,1500).getString("detail_level").equals("city"));ok(AddressPolicy.format(new JSONObject().put("city","深圳市"),10).getString("detail_level").equals("city"));ok(AddressPolicy.format(f,Double.NaN).length()==0);ok(AddressPolicy.text(new JSONObject().put("city",new JSONArray()),"city").isEmpty());
  JSONObject bj=AddressPolicy.format(new JSONObject().put("country","中国").put("province","北京市"),100);ok(bj.getString("city").equals("北京市"));ok(bj.getString("display_name").equals("北京市附近"));ok(AddressPolicy.distance(31,121,31,121)==0);ok(AddressPolicy.distance(31,121,31.001,121)>100);
  AtomicInteger calls=new AtomicInteger();List<String> sent=new ArrayList<>();JSONObject raw=AmapAddress.lookup("map-secret",22,113,(route,params)->{sent.add(route+"?"+params);if(calls.getAndIncrement()==0)return new JSONObject().put("status","1").put("locations","113.006000,22.003000");return new JSONObject().put("status","1").put("regeocode",new JSONObject().put("addressComponent",new JSONObject().put("country","中国").put("province","北京市").put("city",new JSONArray()).put("district","海淀区").put("streetNumber",new JSONObject().put("street","测试路"))));});ok(calls.get()==2);ok(sent.get(0).contains("coordsys=gps"));ok(java.net.URLDecoder.decode(sent.get(0),"UTF-8").contains("113.000000,22.000000"));ok(java.net.URLDecoder.decode(sent.get(1),"UTF-8").contains("113.006000,22.003000"));ok(!raw.toString().contains("map-secret"));ok(!raw.has("city"));ok(AddressPolicy.format(raw,5).getString("city").equals("北京市"));
  boolean rejected=false;try{AmapAddress.lookup("secret",22,113,(route,p)->new JSONObject().put("status","0").put("infocode","10001"));}catch(AddressResolver.Unavailable e){rejected=!e.getMessage().contains("secret");}ok(rejected);
  AtomicLong clock=new AtomicLong(100000);AtomicInteger lookups=new AtomicInteger();AddressResolver r=new AddressResolver(clock::get,(p,k,lat,lon)->{lookups.incrementAndGet();return fixture();});r.configure(true,"system","");r.consider(22,113,10);idle(r);ok(r.snapshot(22,113,10).has("address"));r.consider(22,113,10);ok(lookups.get()==1);ok(!r.snapshot(22,113,2000).getJSONObject("address").has("street"));ok(!r.snapshot(22.01,113,10).has("address"));clock.addAndGet(120001);ok(!r.snapshot(22,113,10).has("address"));r.configure(false,"system","");ok(!r.snapshot(22,113,10).has("address"));
  CountDownLatch started=new CountDownLatch(1),release=new CountDownLatch(1);AddressResolver delayed=new AddressResolver(clock::get,(p,k,lat,lon)->{started.countDown();release.await(2,TimeUnit.SECONDS);return fixture();});delayed.configure(true,"system","");delayed.consider(22,113,10);ok(started.await(1,TimeUnit.SECONDS));for(int i=0;i<10;i++)delayed.consider(22,113,10);synchronized(delayed){ok(delayed.outstanding.size()==1);}delayed.configure(false,"system","");release.countDown();idle(delayed);ok(!delayed.snapshot(22,113,10).has("address"));
  CountDownLatch started2=new CountDownLatch(1),release2=new CountDownLatch(1);AddressResolver moved=new AddressResolver(clock::get,(p,k,lat,lon)->{started2.countDown();release2.await(2,TimeUnit.SECONDS);return fixture();});moved.configure(true,"system","");moved.consider(22,113,10);ok(started2.await(1,TimeUnit.SECONDS));moved.consider(22.01,113,10);release2.countDown();idle(moved);ok(!moved.snapshot(22.01,113,10).has("address"));ok(moved.snapshot(22.01,113,10).getString("address_status").contains("丢弃"));
  CountDownLatch start3=new CountDownLatch(1),rel3=new CountDownLatch(1);AddressResolver timeout=new AddressResolver(clock::get,(p,k,lat,lon)->{start3.countDown();rel3.await(2,TimeUnit.SECONDS);return fixture();});timeout.configure(true,"system","");timeout.consider(22,113,10);ok(start3.await(1,TimeUnit.SECONDS));clock.addAndGet(13000);ok(timeout.snapshot(22,113,10).getString("address_status").contains("超时"));rel3.countDown();idle(timeout);ok(!timeout.snapshot(22,113,10).has("address"));
  AddressResolver needsKey=new AddressResolver(clock::get,(p,k,lat,lon)->{throw new AssertionError("must not call without key");});needsKey.configure(true,"amap","");needsKey.consider(22,113,10);ok(needsKey.snapshot(22,113,10).getString("address_status").contains("Key"));
  System.out.println(n+" address-format, accuracy, coordinate-conversion, cache, concurrency and stale-result assertions passed (no network)");
 }
}
